package com.lbos.commercecustomer.entity; import jakarta.persistence.*;import java.util.*;import java.time.*;import java.math.*; @Entity @Table(name="customer_address",indexes=@Index(name="idx_customer_address_customer_profile_id",columnList="customer_profile_id")) public class CustomerAddress {@Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="customer_address_id") private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_profile_id") private CustomerProfile customer; @Column(name="city_id",nullable=false) private UUID cityId; @Column(name="zone_id") private UUID zoneId; @Column(name="address_tag",nullable=false,length=30) private String addressTag="HOME"; @Column(name="address_line_1",nullable=false,length=255) private String line1; @Column(name="address_line_2",length=255) private String line2; @Column(name="postal_code",length=20) private String postalCode; @Column(precision=10,scale=7) private BigDecimal latitude; @Column(precision=10,scale=7) private BigDecimal longitude; @Column(name="is_default",nullable=false) private boolean defaultAddress; public CustomerAddress(){} public UUID getId(){return id;} public void setId(UUID v){id=v;} public CustomerProfile getCustomer(){return customer;} public void setCustomer(CustomerProfile v){customer=v;} public UUID getCityId(){return cityId;} public void setCityId(UUID v){cityId=v;} public UUID getZoneId(){return zoneId;} public void setZoneId(UUID v){zoneId=v;} public String getAddressTag(){return addressTag;} public void setAddressTag(String v){addressTag=v;} public String getLine1(){return line1;} public void setLine1(String v){line1=v;} public String getLine2(){return line2;} public void setLine2(String v){line2=v;} public String getPostalCode(){return postalCode;} public void setPostalCode(String v){postalCode=v;} public BigDecimal getLatitude(){return latitude;} public void setLatitude(BigDecimal v){latitude=v;} public BigDecimal getLongitude(){return longitude;} public void setLongitude(BigDecimal v){longitude=v;} public boolean isDefaultAddress(){return defaultAddress;} public void setDefaultAddress(boolean v){defaultAddress=v;}}